  const units = {
    d: 86400,
    h: 3600,
    m: 60,
    s: 1
  };

  const regex = /([0-9]+)([dhms])/g;
  const matches = [...s.matchAll(regex)];

  // Validar que el texto solo contenga los matches encontrados
  const reconstructed = matches.map(m => m[1] + m[2]).join('');
  if (reconstructed !== s) return null;

  if (matches.length === 0) return null;

  let totalSeconds = 0;
  const seenUnits = new Set();

  for (const match of matches) {
    const value = parseInt(match[1], 10);
    const unit = match[2];

    if (seenUnits.has(unit)) return null;
    seenUnits.add(unit);

    totalSeconds += value * units[unit];
  }

  return totalSeconds;
}

