  const keys = path.replace(/\[(\d+)\]/g, '.$1').split('.').filter(k => k !== '');
  let current = obj;

  for (const key of keys) {
    if (current === null || typeof current !== 'object' || !(key in current)) {
      return defaultValue;
    }
    current = current[key];
  }

  return current === undefined ? defaultValue : current;
}

