function parseDuration(s) {
    if (!s || typeof s !== 'string') return null;

    const units = { d: 86400, h: 3600, m: 60, s: 1 };
    const validChars = /^[0-9dhms]+$/i;
    if (!validChars.test(s)) return null;

    const lowerS = s.toLowerCase();
    const seenUnits = new Set();
    let totalSeconds = 0;

    // Regex to match number followed by unit (case-insensitive)
    const regex = /(\d+)([dhms])/gi;
    let match;

    while ((match = regex.exec(lowerS)) !== null) {
        const num = parseInt(match[1], 10);
        const unit = match[2];

        if (seenUnits.has(unit)) return null; // Unit repeated
        seenUnits.add(unit);

        totalSeconds += num * units[unit];
    }

    // Check if there are any characters left that don't match the pattern (e.g., letters without numbers)
    const remaining = lowerS.replace(regex, '');
    if (remaining.length > 0) return null;

    return totalSeconds;
}

